import type { ReactNode } from "react";

/*
 * Plain substring matching for short, known lists (select options, pages in
 * the nav search). Every word of the query has to appear somewhere in the
 * haystack, in any order, so "derm syd" finds "Sydney Dermatology". No fuzzy
 * scoring: with lists this size a predictable filter beats a clever one.
 */

/** Lower-cased words of a query, empty when there is nothing to filter by. */
export function queryWords(query: string): string[] {
  return query.trim().toLowerCase().split(/\s+/).filter(Boolean);
}

/** True when every query word appears in at least one of the texts. */
export function matchesQuery(words: ReadonlyArray<string>, ...texts: Array<string | undefined>): boolean {
  if (words.length === 0) return true;
  const haystack = texts.filter(Boolean).join(" ").toLowerCase();
  return words.every((w) => haystack.includes(w));
}

/**
 * The text with each query word marked. Overlapping hits merge into one mark,
 * so "de" and "derm" in the same query never nest.
 */
export function highlightMatches(text: string, words: ReadonlyArray<string>, markClassName: string): ReactNode {
  if (words.length === 0) return text;
  const lower = text.toLowerCase();
  const hits: Array<[number, number]> = [];
  for (const w of words) {
    let from = 0;
    while (from <= lower.length - w.length) {
      const at = lower.indexOf(w, from);
      if (at === -1) break;
      hits.push([at, at + w.length]);
      from = at + w.length;
    }
  }
  if (hits.length === 0) return text;
  hits.sort((a, b) => a[0] - b[0]);
  const merged: Array<[number, number]> = [];
  for (const [s, e] of hits) {
    const last = merged[merged.length - 1];
    if (last && s <= last[1]) last[1] = Math.max(last[1], e);
    else merged.push([s, e]);
  }

  const out: ReactNode[] = [];
  let cursor = 0;
  merged.forEach(([s, e], i) => {
    if (s > cursor) out.push(text.slice(cursor, s));
    out.push(
      <mark key={i} className={markClassName}>
        {text.slice(s, e)}
      </mark>,
    );
    cursor = e;
  });
  if (cursor < text.length) out.push(text.slice(cursor));
  return out;
}

/* Field-size search. the reference grey frosted control (the Select field and
   the filter chips): recessed fill, blur, lit top edge and darker bottom
   inset, so search reads as part of the page's controls rather than a data
   entry box. It lifts toward white on focus because it takes typing, and the
   border turns accent with the halo, as TextInput does. The flat preset is square
   and neutral through the tokens alone. */

.box {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  border: var(--input-border-width, var(--border-w-field)) solid transparent;
  border-radius: var(--input-radius, var(--r-md));
  background: var(--recess-fill);
  -webkit-backdrop-filter: var(--blur-recess);
  backdrop-filter: var(--blur-recess);
  box-shadow: var(--shadow-recess);
  color: var(--ink-muted);
  transition:
    background-color var(--dur) var(--ease),
    border-color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease),
    color var(--dur) var(--ease);
}

.md {
  min-height: var(--input-height-md, var(--field-h-md));
}

.sm {
  min-height: var(--input-height-sm, var(--field-h-sm));
  border-radius: var(--input-radius, var(--r-sm));
}

.box:hover:not(.disabled) {
  background: var(--recess-fill-hover);
}

.box:focus-within:not(.disabled) {
  border-color: var(--field-focus-border, rgba(var(--rgb-brand), 0.7));
  background: rgba(var(--rgb-white), 0.78);
  box-shadow: var(--shadow-recess), var(--field-focus-ring, var(--focus-halo));
  color: var(--ink-brand);
}

/* A query is doing something to the page: the icon takes the brand ink. */
.filled {
  color: var(--ink-brand);
}

.invalid,
.invalid:hover:not(.disabled) {
  border-color: rgba(var(--rgb-danger), 0.75);
  background: rgba(var(--rgb-danger), 0.06);
}

.invalid:focus-within:not(.disabled) {
  border-color: var(--danger-base);
  box-shadow: var(--shadow-recess), var(--field-focus-ring-invalid, 0 0 0 4px rgba(var(--rgb-danger), 0.14));
}

.disabled {
  background: rgba(var(--rgb-brand-deep), 0.05);
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  box-shadow: none;
  color: var(--ink-disabled);
}

.leading {
  display: inline-flex;
  flex-shrink: 0;
  padding-left: 13px;
}

.sm .leading {
  padding-left: 11px;
}

.input {
  flex: 1;
  min-width: 0;
  height: 100%;
  padding: calc(10px * var(--density)) calc(12px * var(--density)) calc(10px * var(--density)) calc(9px * var(--density));
  border: 0;
  outline: none;
  background: transparent;
  font-family: var(--font-body);
  font-size: var(--input-font-size, var(--text-input));
  color: var(--ink-body);
}

/* Focus is drawn on the whole box (.box:focus-within), icon and clear
   button included. (0,2,0) outranks globals.css's :focus-visible fallback. */
.input:focus,
.input:focus-visible {
  outline: none;
}

.sm .input {
  padding: 6px 10px 6px 8px;
  font-size: var(--text-body);
}

/* On the recess the lighter placeholder ink falls to ~3.5:1; muted holds. */
.input::placeholder {
  color: var(--ink-muted);
  opacity: 1;
}

.input:disabled {
  cursor: not-allowed;
  color: var(--ink-disabled);
  -webkit-text-fill-color: var(--ink-disabled);
}

.input:disabled::placeholder {
  color: var(--ink-disabled);
}

.input::-webkit-search-cancel-button,
.input::-webkit-search-decoration {
  -webkit-appearance: none;
  appearance: none;
  display: none;
}

/* Clear: inset 7px from a 10px box, so its radius steps down to 6. */
.clear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  margin-right: 7px;
  padding: 0;
  border: 0;
  border-radius: var(--r-xs);
  background: transparent;
  color: var(--ink-muted);
  transition:
    background-color var(--dur) var(--ease),
    color var(--dur) var(--ease);
}

.sm .clear {
  width: 24px;
  height: 24px;
  margin-right: 5px;
  border-radius: var(--r-2xs);
}

.clear:hover {
  background: var(--wash-active);
  color: var(--ink-brand);
}

.clear:active {
  background: var(--wash-strong);
}

.clear:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* Key hint: the reference esc badge, a raised key on the recess. */
.kbd {
  flex-shrink: 0;
  margin-right: 10px;
  padding: 2px 6px;
  border-radius: var(--r-2xs);
  background: rgba(var(--rgb-white), 0.75);
  box-shadow:
    inset 0 -1px 0 rgba(var(--rgb-brand-deep), 0.14),
    0 0 0 1px rgba(var(--rgb-brand-deep), 0.1);
  font-family: var(--font-body);
  font-size: var(--text-micro);
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 16px;
  color: var(--ink-muted);
  white-space: nowrap;
  transition: opacity var(--dur) var(--ease);
}

.box:focus-within .kbd {
  opacity: 0;
}

.disabled .kbd {
  color: var(--ink-disabled);
}

"use client";

import { useRef, type ComponentPropsWithRef, type KeyboardEvent } from "react";
import { cx } from "../_internal/cx";
import { mergeRefs } from "../_internal/merge-refs";
import { mergeDescribedBy, useField } from "../Field/Field";
import { IconSearch, IconX } from "../Icon/Icon";
import { Spinner } from "../Spinner/Spinner";
import { useGlobalShortcut, useShortcutLabel } from "./shortcut";
import styles from "./SearchField.module.css";

export type SearchFieldProps = Omit<
  ComponentPropsWithRef<"input">,
  "size" | "type" | "value" | "defaultValue" | "onChange" | "children"
> & {
  value: string;
  onValueChange: (value: string) => void;
  /** md sits level with TextInput and Select; sm with the 36px controls. */
  size?: "sm" | "md";
  /** Results are being fetched. The magnifier turns into a spinner and the field reports busy. */
  loading?: boolean;
  /** Announced while loading. */
  loadingLabel?: string;
  /**
   * A letter that focuses the field with Ctrl/⌘. Shows as a key badge while
   * the field is empty and unfocused. Use once per page.
   */
  shortcut?: string;
  /** Enter runs this (and never submits an enclosing form). Omit for live filtering. */
  onSearch?: (value: string) => void;
  invalid?: boolean;
  /** Class for the outer box rather than the <input>. */
  boxClassName?: string;
};

/**
 * Field-size search box: the reference recessed grey frosted control at form
 * height, for page-level search (a customer list, the order queue). The
 * 32px filter-bar version is FilterSearch.
 *
 * Escape clears (and stops there, so an enclosing modal stays open); a second
 * Escape on an empty field is left to bubble. The clear button returns focus
 * to the input so the next search can be typed straight away.
 */
export function SearchField({
  value,
  onValueChange,
  size = "md",
  loading = false,
  loadingLabel = "Searching…",
  shortcut,
  onSearch,
  invalid: invalidProp,
  boxClassName,
  className,
  id: idProp,
  disabled,
  placeholder = "Search",
  onKeyDown,
  ref,
  "aria-describedby": describedByProp,
  ...rest
}: SearchFieldProps) {
  const field = useField();
  const inputRef = useRef<HTMLInputElement>(null);
  const invalid = invalidProp ?? field?.invalid ?? false;
  const shortcutLabel = useShortcutLabel(shortcut);

  useGlobalShortcut(disabled ? undefined : shortcut, () => {
    inputRef.current?.focus();
    inputRef.current?.select();
  });

  const clear = () => {
    onValueChange("");
    inputRef.current?.focus();
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    onKeyDown?.(e);
    if (e.defaultPrevented) return;
    if (e.key === "Escape" && value) {
      e.preventDefault();
      e.stopPropagation();
      onValueChange("");
    } else if (e.key === "Enter" && onSearch) {
      e.preventDefault();
      onSearch(value);
    }
  };

  const iconSize = size === "sm" ? 14 : 16;

  return (
    <div data-slot="search-field"
      className={cx(
        styles.box,
        styles[size],
        value && styles.filled,
        invalid && styles.invalid,
        disabled && styles.disabled,
        boxClassName,
      )}
    >
      <span className={styles.leading} aria-hidden="true">
        {loading ? <Spinner size={iconSize} tone="current" /> : <IconSearch size={iconSize} />}
      </span>
      <input
        ref={mergeRefs(inputRef, ref)}
        id={idProp ?? field?.id}
        type="search"
        value={value}
        placeholder={placeholder}
        disabled={disabled}
        autoComplete="off"
        spellCheck={false}
        aria-invalid={invalid || undefined}
        aria-busy={loading || undefined}
        aria-describedby={mergeDescribedBy(describedByProp, field?.describedBy)}
        aria-keyshortcuts={shortcut ? `Control+${shortcut.toUpperCase()} Meta+${shortcut.toUpperCase()}` : undefined}
        className={cx(styles.input, className)}
        onChange={(e) => onValueChange(e.target.value)}
        onKeyDown={handleKeyDown}
        {...rest}
      />
      {value && !disabled ? (
        <button type="button" className={styles.clear} aria-label="Clear search" onClick={clear}>
          <IconX size={size === "sm" ? 13 : 14} />
        </button>
      ) : shortcutLabel ? (
        <kbd className={styles.kbd} aria-hidden="true">
          {shortcutLabel}
        </kbd>
      ) : null}
      <span className="sr-only" role="status">
        {loading ? loadingLabel : ""}
      </span>
    </div>
  );
}

"use client";

import { useEffect, useRef, useSyncExternalStore } from "react";

const subscribe = () => () => {};
const isApple = () => /Mac|iPhone|iPad|iPod/.test(navigator.platform || navigator.userAgent);

/**
 * "⌘ K" on Apple platforms, "Ctrl K" elsewhere. The server snapshot is the
 * Ctrl form, so SSR and the first client render agree; Macs swap after
 * hydration without a mismatch warning.
 */
export function useShortcutLabel(key: string | undefined): string | null {
  const apple = useSyncExternalStore(subscribe, isApple, () => false);
  if (!key) return null;
  return `${apple ? "⌘" : "Ctrl"} ${key.toUpperCase()}`;
}

/**
 * Ctrl/⌘ + key anywhere on the page runs the handler. Ignored while a modal
 * dialog is open, so a shortcut can't pull focus out from behind a focus trap.
 */
export function useGlobalShortcut(key: string | undefined, handler: () => void): void {
  const latest = useRef(handler);
  useEffect(() => {
    latest.current = handler;
  });

  useEffect(() => {
    if (!key) return;
    const want = key.toLowerCase();
    const onKeyDown = (e: KeyboardEvent) => {
      if (!(e.ctrlKey || e.metaKey) || e.altKey || e.shiftKey) return;
      if (e.key.toLowerCase() !== want) return;
      if (document.querySelector('[aria-modal="true"]')) return;
      e.preventDefault();
      latest.current();
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [key]);
}
